fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Ensure all vectors have the same length
    assert_eq!(dst.len(), src.len(), "dst and src must have the same length");
    assert_eq!(dst.len(), mask.len(), "dst and mask must have the same length");

    // Create a new vector to hold the result
    let mut result = Vec::with_capacity(dst.len());

    // Iterate through the indices and select elements based on the mask
    for i in 0..dst.len() {
        if mask[i] {
            result.push(src[i]);
        } else {
            result.push(dst[i]);
        }
    }

    result
}